}
std::vector<std::uint8_t> tmp(static_cast<std::size_t>(size));
int err = lfs->cfg->read(lfs->cfg, block, off, tmp.data(), size);
if (err < 0) {
    return err;
}
int cmp = std::memcmp(buffer, tmp.data(), static_cast<std::size_t>(size));
if (cmp < 0) {
    return LFS_CMP_LT;
}
if (cmp > 0) {
    return LFS_CMP_GT;
}
return LFS_CMP_EQ;

